func parsePlatformWindowTime(raw string, location *time.Location) (time.Time, bool, bool) {
	for _, layout := range []string{time.RFC3339Nano, time.RFC3339} {
		if parsed, err := time.Parse(layout, raw); err == nil {
			return parsed.In(location), false, true
		}
	}
	for _, layout := range []string{"2006-01-02", "2006/01/02"} {
		if parsed, err := time.ParseInLocation(layout, raw, location); err == nil {
			return parsed, true, true
		}
	}
	return time.Time{}, false, false
}

func parsePlatformLookback(raw string) (time.Duration, int, bool) {
	raw = strings.ToLower(strings.TrimSpace(raw))
	if len(raw) < 2 {
		return 0, 0, false
	}
	amount, err := strconv.Atoi(raw[:len(raw)-1])
	if err != nil || amount < 1 {
		return 0, 0, false
	}
	switch raw[len(raw)-1] {
	case 'h':
		return time.Duration(amount) * time.Hour, 0, true
	case 'd':
		return 0, amount, true
	case 'w':
		return 0, amount * 7, true
	}
	return 0, 0, false
}

